  'settings.connections.typeHint': 'Ingen og Direkte betyder ikke det samme. Ingen er uvirksom: den udpeger ingen forbindelse og bruges aldrig, så den består kun, indtil du er færdig med at udfylde den. Direkte er et rigtigt valg: trafikken går ud over denne maskines egen forbindelse og uden om enhver proxy for de værter, der står nedenfor. Sådan holder du en NAS uden for en proxy, der gælder hele appen. En række, hvis filter passer på værten, slår en række uden filter, så en direkte række med filter vinder altid over en proxy, der tager alt.',
