  'settings.connections.passwordHint': 'En gemt adgangskode sendes aldrig til denne side, derfor er feltet tomt. Lad det stå tomt, og den gemte beholdes. En gemt adgangskode følger ikke rækken til en anden vært, port eller type: ændrer du en af dem, skal den sættes igen.',
  'settings.connections.filter': 'Værtsfilter',
