  'settings.reconnect.method.script': 'Script',
  'settings.reconnect.offState': 'Genforbindelse er slået fra. Intet beder routeren om en ny adresse, og en hostergrænse overlades til den sædvanlige ventetid mellem forsøgene.',

  'settings.reconnect.command': 'Program',
  'settings.reconnect.commandHint': 'Den fulde sti til det program, der skal køres. Det startes direkte og ikke gennem en shell, så en pipe, en omdirigering eller to kommandoer i træk hører hjemme i metoden “Script”. %%router%%, %%username%%, %%password%% og %%ip%% sættes ind, før det starter.',
  'settings.reconnect.args': 'Argumenter',
  'settings.reconnect.argsHint': 'Ét pr. linje, så et argument med et mellemrum bliver ved med at være ét argument. De samme fire variabler sættes ind her.',

  'settings.reconnect.upnpState': 'Der skal ikke mere til. Gatewayen findes ved at spørge netværket, så det er den metode, der virker uden at vide noget om routeren.',
  'settings.reconnect.upnpLocation': 'Gatewayens beskrivelses-URL',
  'settings.reconnect.upnpLocationHint': 'Valgfrit og normalt tomt. Udfyld det kun der, hvor multicast-søgningen bliver filtreret fra, men selve gatewayen sagtens kan nås, hvilket søgningen alene aldrig kan rette op på.',

  'settings.reconnect.interpreter': 'Fortolker',
  'settings.reconnect.interpreterHint': 'Det program, scriptet gives videre til, med fuld sti: /bin/sh, /bin/bash, /usr/bin/python3.',
