  'settings.reconnect.router': 'Routerens adresse',
  'settings.reconnect.routerHint': 'Routeren i dit eget netværk, uden skema: 192.168.1.1, ikke http://192.168.1.1/. Det er det, %%router%% bliver til. Det er ikke den offentlige adresse, og de to må aldrig byttes om: en loginforespørgsel rettet mod den offentlige sender din routeradgangskode ud på internettet.',
  'settings.reconnect.routerFind': 'Find min router',
