  'settings.reconnect.passwordStored': 'gemt, og sendes aldrig tilbage hertil',
  'settings.reconnect.passwordHint': 'En gemt adgangskode sendes aldrig tilbage til denne side, og derfor er feltet tomt: lad det stå tomt, så beholdes den gemte. Skriv en ny for at erstatte den. Vil du fjerne den helt, så skriv noget og ryd feltet igen.',

  'settings.reconnect.requests': 'Forespørgsler',
  'settings.reconnect.requestsHint': 'Afspilles i rækkefølge, og kørslen stopper ved den første, routeren ikke svarer på. Det er JDownloaders LiveHeader-metode: som regel et login og derefter genstarten eller afbrydelsen. Alle felter tager variablerne.',
