  'settings.reconnect.importLabel': 'LiveHeader- eller curl-script',
  'settings.reconnect.importHint': 'Indsæt et JDownloader-genforbindelsesscript, markører og det hele. Dets variabler oversættes på vejen ind, og %%%routerip%%% bliver til routerens adresse i stedet for den offentlige, for her er de to forskellige ting.',
