  'settings.reconnect.checkTitle': 'Kontrol af adressen',
  'settings.reconnect.checkUrl': 'URL til IP-kontrol',
  'settings.reconnect.checkUrlHint': 'Hentes, før metoden kører, og igen bagefter; kørslen tæller som færdig, så snart den adresse, siden viser, har ændret sig. Der er ingen standard: en downloadmanager, du selv hoster, skal ikke begynde at melde din adresse til en tjeneste, du aldrig har valgt. Det, siden viser, skal være den adresse, internettet ser, for en side, der gengiver adressen på dit eget netværk, kan ikke skelne en genopkobling fra en kørsel, der intet gjorde.',
  'settings.reconnect.checkPresets': 'Kendte tjenester',
  'settings.reconnect.checkPresetsHint': 'En genvej til den, der ikke har nogen præference, ikke en standard: ingen af dem vælges for dig, og enhver side, der skriver din offentlige adresse, gør det lige så godt.',
  'settings.reconnect.interval': 'Sekunder mellem kontrollerne (1 til 60)',
  'settings.reconnect.intervalHint': "Hvor længe der ventes mellem to kig på kontrol-URL'en, når metoden har kørt. Der er en nedre grænse, for en løkke uden en gør kontroltjenesten til et mål.",
  'settings.reconnect.timeout': 'Sekunder der kontrolleres (5 til 900)',
  'settings.reconnect.timeoutHint': 'How long to keep looking before the run is called a failure. A reconnect still waiting a quarter of an hour later has failed whatever this says. A timeout below the interval is raised to it, or the run would be over before a single check happened. The Command and Script methods give their program the same number of seconds to finish before the checking starts; one still running then is stopped, and the run fails.',
