  'settings.access.relay.title': 'Projektets relæ',
  'settings.access.relay.body': 'Et relay er en mellemmand, der gør alle dine instanser tilgængelige uden for hjemmenetværket, altså alle steder fra. Dette stilles gratis til rådighed af projektet.',
  'settings.access.relay.use': 'Brug projektets relæ',
  'settings.access.relay.leadProject': 'Virker uden opsætning. Alt, hvad dine instanser siger til hinanden, er krypteret, og kun du har nøglen.',
  'settings.access.relay.seesButton': 'Hvad ser det?',
  'settings.access.relay.seesTip': 'Ikke synligt for relayet: dine links, dine downloads, dine filer og dit adgangstoken.\n\nSynligt for relayet: IP-adresserne på dine instanser og hvornår de sender noget.\n\nDet kan ikke krypteres væk. Hvis det generer dig, så kør dit eget relay.',
  'settings.access.relay.seesAddress': 'Projektets relæ kører på {address}.',
  'settings.access.relay.none': 'Intet relæ',
  'settings.access.relay.noneHint': 'Intet relay er aktivt. På samme netværk, altså dit hjemmenetværk, finder dine instanser stadig hinanden af sig selv. På tværs af netværk når de ikke hinanden, så der er ingen fjernadgang.',
  'settings.access.relay.own': 'Eget relæ',
  'settings.access.relay.project': 'Projektets relæ',
  'settings.access.relay.whichHint': 'Går via {address}',
