  'settings.access.ownRelay.use': 'Brug mit eget relæ',
  'settings.access.ownRelay.lead': 'To veje: denne instans tager relæet, eller du indtaster en adresse.',
  'settings.access.ownRelay.serveLabel': 'Brug denne instans som relay',
  'settings.access.ownRelay.serveHint': 'Virker kun, hvis denne instans kan nås udefra, for eksempel via Nginx Proxy Manager og et eget domæne.',
  'settings.access.ownRelay.serveClients': '{count} forbundet lige nu.',
  'settings.access.ownRelay.addressLabel': 'Adresse',
  'settings.access.ownRelay.addressPlaceholder': 'f.eks. https://relay.mitdomaene.dk',
  'settings.access.ownRelay.save': 'Gem',
  'settings.access.ownRelay.everyInstance': 'Denne adresse gælder kun denne instans. Indtast den på hver instans.',
  'settings.access.ownRelay.containerLabel': 'Som egen container',
  'settings.access.ownRelay.containerHint': 'Hvis ingen af dine instanser kan nås udefra, må relayet stå et andet sted, på din server eller en lille VPS. Installer containeren fra Unraid Community Applications eller med kommandoen nedenfor.\n\nContaineren kræver ingen opsætning: start den, skriv dens adresse ovenfor, færdig. Den gemmer ingenting, så der er intet at sikkerhedskopiere.',
