  'settings.access.identity.nameLabel': 'Navn',
  'settings.access.identity.namePlaceholder': 'f.eks. Hjemmeserver',
  'settings.access.identity.nameHint': 'Tilbydes først ved parring og i QR-koden nedenfor i stedet for det navn, operativsystemet eller containerkørselsmiljøet tilfældigvis giver denne maskine. Valgfrit: lad det stå tomt for at blive ved med at bruge det navn.',
  'settings.access.identity.domainsLabel': 'Kendte domæner',
  'settings.access.identity.domainsHint': 'Hvert domæne huskes automatisk, første gang en forespørgsel kommer ind via det, og bliver stående her, selv når senere forespørgsler i stedet kommer via LAN-IP\'en. Tilføj et domæne i hånden, hvis det allerede er sat op, men der endnu ikke er kommet en forespørgsel via det. Én fuld adresse pr. linje, f.eks. https://kl.example.com.',
  'settings.access.cardTitle': 'Forbind instanser og fjernadgang',
  'settings.access.phrase.body': 'Én sætning forbinder alle de KnightLoadere, du kører. Opret den her, og indsæt den derefter i dine andre instanser. Du behøver ingen konto eller login, og der er intet at konfigurere.',
  'settings.access.phrase.noPasswordWarning': 'Denne instans har ingen adgangskode. Sætningen når hver instans, du forbinder med den, så enhver, der kan læse den her, når dem alle - ikke kun denne. Sæt hellere en adgangskode ovenfor først.',
  'settings.access.phrase.activate': 'Opret en sætning',
  'settings.access.phrase.howStep1': 'Tryk på "{button}" på denne instans. Der kommer tolv ord frem.',
  'settings.access.phrase.howStep2': 'Åbn KnightLoader på den anden maskine, gå ind på denne side, tryk på "{button}" og skriv de tolv ord.',
  'settings.access.phrase.howStep3': 'Færdig! Hver instans dukker nu op hos den anden under “Instanser”, og du kan styre begge fra begge. Med relayet slået til er dine instanser tilgængelige uden for dit netværk.',
  'settings.access.phrase.howWhat': 'Ordene er en hemmelighed, ikke en adresse. Hver instans regner to nøgler ud af dem: en til at finde de andre, en til at kryptere.\n\nFor at finde hinanden ringer hver instans selv op til det samme mødested på internettet. Den, der viser den samme nøgle, bliver forbundet. Derfor behøver ingen af dine instanser at kunne nås udefra.\n\nMødestedet kan ikke læse med. Det ser aldrig dine ord, og alt, der passerer det, er krypteret med den anden nøgle.',
  'settings.access.phrase.statusDisconnected': 'Ikke forbundet',
  'settings.access.phrase.statusHintProject': 'Forbundet til projektets relay. Fjernadgang er sat op.',
  'settings.access.phrase.statusHintOwn': 'Forbundet til dit eget relay. Fjernadgang er sat op.',
  'settings.access.phrase.statusHintOff': 'Intet relay er aktivt. Dine instanser kan kun nås på det lokale netværk.',
  'settings.access.phrase.statusHintLost': 'Ingen kontakt med relayet. KnightLoader bliver ved med at prøve. Indtil da når dine instanser kun hinanden på det lokale netværk.',
  'settings.access.phrase.statusConnected': 'Forbundet',
  'settings.access.phrase.howButton': 'Hvordan virker det?',
  'settings.access.phrase.joinButton': 'Indtast frasen',
  'settings.access.phrase.joinPlaceholder': 'Indsæt de tolv ord fra din anden instans',
  'settings.access.phrase.joinConfirm': 'Forbind',
  'settings.access.phrase.errChecksum': 'Den sætning er ikke gyldig. Se efter et ord, der er stavet forkert eller byttet om.',
  'settings.access.phrase.errUnknownWord': 'Ord {position} ("{word}") er ikke et af de tilladte ord.',
  'settings.access.phrase.errWordCount': 'Det er {count} ord. En sætning skal have {need}.',
  'settings.access.phrase.errExists': 'Denne instans har allerede en sætning. Forlad gruppen først for at starte en ny.',
  'settings.access.phrase.yourPhrase': 'Din forbindelsessætning',
  'settings.access.phrase.pasteHint': 'Indsæt disse tolv ord i hver anden instans, du vil forbinde.',
  'settings.access.phrase.qrHint': 'Eller scan dette fra den anden enhed i stedet for at taste.',
  'settings.access.phrase.revealWhy': 'Indtast denne instans adgangskode for at vise sætningen igen. Den åbner hver instans i gruppen, ikke kun denne.',
  'settings.access.phrase.revealConfirm': 'Vis',
