  'settings.browsertools.qrCode': 'QR-kode',
  'settings.browsertools.desktopTitle': 'Skrivebordsapp',
  'settings.browsertools.desktopHint': 'KnightLoader som et program på din computer, med denne brugerflade i sit eget vindue. Hver download er den nyeste udgivelse.',
  'settings.browsertools.serverTitle': 'På en server',
  'settings.browsertools.serverHint': 'På en server bliver KnightLoader ved med at downloade, mens denne computer er slukket. Installer det fra Unraids Community Applications, kør det som en Docker-container, eller byg det fra kildekoden.',
  'settings.browsertools.dockerHint': 'Et klik kopierer kommandoen, der starter containeren:',
  'settings.browsertools.sourceZip': 'Kildekode.zip',
  'settings.browsertools.installPwaLabel': 'Eller installer denne side som en app',
  'settings.browsertools.install': 'Installér',
  'settings.browsertools.installIOS':
    'På iPhone eller iPad: åbn denne side i Safari, tryk på Del, og derefter „Føj til hjemmeskærm“.',
  'settings.nav.browsertools': 'App',
  'settings.browsertools.bookmarkletStep1': 'Træk knappen nedenfor op på din browsers bogmærkelinje. Den gemmes som ethvert andet bogmærke, og intet bliver installeret.',
  'settings.browsertools.bookmarkletStep2': 'Klik på den på en hvilken som helst side (marker først noget tekst, hvis du kun vil have den). Der åbnes en lille KnightLoader-fane med sidens link, eller den markerede tekst, allerede udfyldt. Gennemse det, og tilføj det derfra som en download.',
  'settings.browsertools.installLabel': 'Sådan installerer du den',
  'settings.browsertools.installChromiumStep1': 'Udpak den downloadede fil.',
  'settings.browsertools.installChromiumStep2': 'Åbn chrome://extensions (eller edge://extensions, brave://extensions).',
  'settings.browsertools.installChromiumStep3': 'Slå udviklertilstand til.',
  'settings.browsertools.installChromiumStep4': 'Vælg „Indlæs upakket” og vælg den udpakkede mappe.',
  'settings.browsertools.installChromiumStep5': 'Klik på puslespilsbrikken ved adresselinjen og fastgør KnightLoader, Chrome lægger ikke nye udvidelser i værktøjslinjen af sig selv.',
  'settings.browsertools.installFirefoxStep1': 'For permanent installation: åbn about:addons og klik på tandhjulsikonet øverst til højre.',
  'settings.browsertools.installFirefoxStep2': 'Vælg „Installer tilføjelse fra fil…” og vælg denne fil.',
  'settings.browsertools.installFirefoxStep3': 'Vil du hellere prøve hurtigt, så åbn about:debugging#/runtime/this-firefox og vælg „Indlæs midlertidig tilføjelse“. Tilføjelsen forsvinder, når Firefox genstarter.',
