  'settings.nav.resolvers': 'Resolvere',
  'settings.module.ytdlp': 'yt-dlp',
  'settings.resolvers.moduleUnavailable': 'Modul ikke tilgængeligt',
  'settings.resolvers.moduleUnavailableHint': 'Alt nedenfor bliver stadig gemt og træder i kraft, så snart yt-dlp bliver tilgængeligt. Intet, du ændrer nu, går tabt.',
  'settings.resolvers.about': 'Konfiguration af yt-dlp-backenden, som henter de medie- og streamingsider, yt-dlp selv understøtter. Hvilken tjeneste der overhovedet håndterer et link (yt-dlp, en debrid-konto eller JDownloader-backenden), afgøres af prioritetsrækkefølgen på siden Konti. Her indstiller du, hvad yt-dlp gør, når et link er sendt videre til det.',
  'settings.resolvers.quality': 'Kvalitet',
  'settings.resolvers.videoFormat': 'Videoformat',
  'settings.resolvers.qualityHint': 'Hvilken -f-vælger yt-dlp startes med. Bedste tilgængelige er yt-dlps eget standardvalg, og hvad hver download brugte, før denne indstilling fandtes.',
  'settings.resolvers.quality.best': 'Bedste tilgængelige',
