  'settings.nav.torrents': 'Torrents',
  'settings.module.torrents': 'Built-in torrent client',
  'settings.torrents.title': 'Torrents',
  'settings.torrents.seedingTitle': 'Seedning',
  'settings.torrents.seedRatio': 'Mål for seedratio',
  'settings.torrents.seedRatioHint': 'Bliver ved med at seede en færdig torrent, indtil denne andel, i forhold til dens egen størrelse, er givet tilbage til sværmen. 0 = intet ratiomål.',
  'settings.torrents.seedDuration': 'Mål for seedvarighed',
  'settings.torrents.seedDurationHint': 'Bliver ved med at seede en færdig torrent så længe efter den er fuldført. 0 = ingen tidsgrænse. Det af de to mål ovenfor, der nås først, stopper seedningen.',
  'settings.torrents.seedDurationUnit': 'timer',
  'settings.torrents.transferTitle': 'Overførselsgrænse',
  'settings.torrents.uploadLimit': 'Uploadgrænse',
  'settings.torrents.uploadLimitHint': 'Begrænser, hvor hurtigt en torrent uploader til sværmen under seedning. 0 = ubegrænset.',
  'settings.torrents.portTitle': 'Port og mapping',
  'settings.torrents.port': 'Port',
  'settings.torrents.portHint':
    'The port this instance listens for swarm connections on. 0 lets the built-in torrent client pick one.',
  'settings.torrents.portRestartHint': 'Motoren bygger kun sin torrentklient én gang, så en ny port træder først i kraft, når denne instans er genstartet. At bede routeren om at mappe den virker med det samme, uanset om en torrent allerede lytter på den.',
  'settings.torrents.portMapHint': 'Beder routeren om at videresende porten ovenfor til denne maskine via UPnP, så peers bag en anden router alligevel kan nå den. Ikke alle routere understøtter dette, og nogle accepterer anmodningen, uden at det reelt virker.',
  'settings.torrents.portMapButton': 'Prøv UPnP-mapping',
  'settings.torrents.portMapping': 'Spørger routeren…',
  'settings.torrents.portMapNeedsPort': 'Angiv en port ovenfor, før du mapper den. Med 0 har routeren intet at videresende til.',
  'settings.torrents.portMapConfirmed': 'Bekræftet: port {port} er mappet og er verificeret som tilgængelig.',
  'settings.torrents.portMapUnconfirmed': 'Routeren accepterede anmodningen, men det kunne ikke bekræftes, at mappingen virker. Nogle routere accepterer anmodningen i stilhed uden at udføre den. Prøv et forbindelsestjek uden for netværket.',
  'settings.torrents.portMapFailed': 'Kunne ikke mappe porten: {error}',
  'settings.torrents.portMapUnavailable': 'Denne build tilbyder endnu ikke portmapping.',
  'settings.torrents.networkTitle': 'Peer-søgning',
  'settings.torrents.dht': 'DHT',
  'settings.torrents.dhtHint': 'Finder peers helt uden en tracker, ved at bruge andre BitTorrent-klienter som et distribueret opslag.',
  'settings.torrents.pex': 'Peer exchange (PEX)',
  'settings.torrents.pexHint': 'Udveksler kendte peers med dem, der allerede er forbundet, så en sværm med få peers findes hurtigere.',
  'settings.torrents.privateNote': 'En privat torrent slår automatisk begge fra, så snart dens metadata kendes, uanset hvad der er indstillet her: med det samme for en uploadet .torrent-fil, eller så snart et magnetlinks egne metadata ankommer fra sværmen. De fleste private trackere udelukker konti, der bruger en af dem.',
  'container.noJD': 'den er krypteret, og kun en JDownloader-backend kan åbne den. Der er ikke sat nogen op: sæt KL_JD til en JDownloader, som denne instans kan nå, og genstart derefter.',
  'container.jdOff': 'den er krypteret, og kun JDownloader-backenden kan åbne den. „JDownloader-backend“ er slået fra på siden Moduler.',
  'torrent.staging': 'Tilføjer…',
