  'torrent.stagedIn': '{file} tilføjet til samleren i „{pkg}“.',
  'torrent.duplicate': '{file} er allerede på listen.',
  'torrent.onlyOne': 'kun én .torrent kan gennemgås ad gangen',
  'torrent.tree.summary': '{n} af {total} fil(er) valgt ({size})',
  'torrent.tree.private': 'Privat tracker',
  'torrent.tree.selectAll': 'Vælg alle',
  'torrent.tree.selectNone': 'Vælg ingen',
  'torrent.tree.cancel': 'Annuller',
  'torrent.tree.add': 'Tilføj til samleren',

  'settings.torrents.notApplied': 'Dette build anvender endnu ikke to af indstillingerne nedenfor. Uploadgrænsen gemmes og kontrolleres, men motoren kan ikke anvende den på en igangværende download. DHT og PEX når heller ikke en almindelig torrent: den seeder med begge slået til, uanset hvad der er indstillet her. En privat torrent fungerer anderledes, som (i) ved „Peer-søgning“ forklarer.',
  'onboarding.step': 'Trin {n} af {total}',
  'onboarding.skip': 'Spring over',
  'onboarding.back': 'Tilbage',
  'onboarding.next': 'Næste',
  'onboarding.finish': 'Færdig',
  'onboarding.welcome.title': 'Velkommen til KnightLoader',
  'onboarding.welcome.body': 'KnightLoader er en downloadmanager, du selv hoster. Indsæt eller slip et link, så henter den passende backend det: den indbyggede motor til almindelige fillinks, yt-dlp til mediesider, en debrid-tjeneste til hostere, du allerede betaler for, eller en headless JDownloader til alt andet. Denne korte rundvisning dækker den ene indstilling, der er værd at tjekke, før du går i gang.',
  'onboarding.welcome.langLabel': 'Grænsefladesprog',
  'onboarding.folder.title': 'Hvor skal filerne havne?',
  'onboarding.folder.body': 'Dette er mappen, som færdige downloads skrives til. Skriv en sti, eller gennemse serveren efter en. Du kan altid ændre den igen på indstillingssiden Generelt.',
  'onboarding.accounts.title': 'Premium-hosts, når du vil have dem',
  'onboarding.accounts.body': 'Køen virker helt uden konto. Når du vil have fuld hastighed hos en hoster eller debrid-tjeneste, du allerede betaler for, så tilføj dens login under Konti. Intet af dette skal sættes op nu.',
  'onboarding.accounts.link': 'Åbn Konti',
  'onboarding.finished.title': 'Du er klar',
  'onboarding.finished.body': 'Så er rundvisningen slut. Siden Hjælp under Indstillinger har en fuld gennemgang af alt andet, denne udgave kan, og de fleste kontroller har deres egen forklaring bag et (i)-ikon.',

