  'settings.categories.add': 'Tilføj kategori',
  'settings.categories.remove': 'Fjern',
  'settings.categories.empty': 'Ingen kategorier endnu.',
  'settings.categories.emptyHint': 'En kategori holder en mappe og et par standardvalg under ét navn, så du vælger navnet i stedet for at beskrive den samme ting igen.',
  'settings.categories.duplicate': 'Der findes allerede en kategori med dette navn.',
  'settings.categories.full': 'Tabellen er fuld ved {max} kategorier.',
  'settings.resolvers.presetAdd': 'Tilføj hoster',
  'settings.resolvers.presetRemove': 'Fjern',
  'settings.resolvers.presetsEmpty': 'Ingen hoster har sine egne standardvalg endnu.',
  'settings.resolvers.presetHost': 'Hoster',
  'settings.resolvers.presetHostHint': 'Det websted, disse standarder gælder for, fx youtube.com. Det gemmes med små bogstaver og uden „www.“ foran, og det virker også at indsætte en hel adresse: kun værten beholdes. For de store videosider dækker en post også deres andre adresser: youtube.com dækker også youtu.be og m.youtube.com. En hoster uden post her starter med alle varianter slået til i bedste kvalitet.',
