  'settings.feeds.status': 'Status',
  'settings.feeds.statusPolling': 'Bliver tjekket',
  'settings.feeds.statusNotPolling': 'Bliver ikke tjekket',
  'settings.feeds.statusUnknown': 'Ikke tjekket endnu, siden serveren startede',
  'settings.feeds.lastPolled': 'Sidst tjekket',
  'settings.feeds.lastPolledNever': 'Ikke tjekket endnu',
  'settings.feeds.lastPolledHint': 'Hvornår dette abonnement sidst blev set på, uanset om opslaget virkede. Angivelsen går tabt, når serveren genstarter, mens det, abonnementet allerede har tilføjet, ikke gør. Et feed, du har fulgt i månedsvis, står derfor som utjekket de par sekunder, der følger efter en genstart.',
  'settings.feeds.pollFailed': 'Det seneste tjek mislykkedes',
  'settings.feeds.notPolledReason': 'Dette abonnement bliver slet ikke tjekket',
  'settings.feeds.seededYes': 'Klar, kun nyt bliver tilføjet',
  'settings.feeds.seededNo': 'Det første tjek står stadig tilbage, og indtil det er kørt, bliver der ikke tilføjet noget',
  'settings.feeds.seededHint': 'Det første tjek af et nyt abonnement noterer alt, hvad feedet fører i det øjeblik, og tilføjer intet af det, så du ikke får en udgivers hele bagkatalog ind på én gang. Kun det, der dukker op derefter, bliver tilføjet.',
  'settings.feeds.remembered': '{n} poster husket',
  'settings.feeds.rememberedHint': 'Hvor mange poster dette abonnement genkender igen, så de ikke bliver tilføjet en gang til, mens feedet stadig leverer dem. Højst 500 pr. abonnement. De ældste ryger først ud, og en post, der stadig står i feedet, er aldrig blandt dem.',
  'settings.feeds.test': 'Test',
  'settings.feeds.testBusy': 'Henter…',
  'settings.feeds.testHint': 'Henter denne adresse én gang og viser dig, hvad der står i den, så du kan se de titler, dit filter bliver prøvet mod. Der bliver kun læst: intet havner i samleren, og intet noteres som set, så du kan også trykke på den for en adresse, du endnu ikke har gemt.',
  'settings.feeds.testResult': 'Hvad der står i dette feed',
  'settings.feeds.testFeedName': 'Feed-navn',
  'settings.feeds.testNoName': 'Dette dokument nævner ikke noget navn',
  'settings.feeds.testMatched': '{matched} af {total} poster passer til titelfilteret',
  'settings.feeds.testNoFilter': 'Intet titelfilter, så alle {total} poster bliver taget',
  'settings.feeds.testShowing': 'De første {n} vises',
