  'settings.feeds.testMatchNo': 'Bliver udeladt',
  'settings.feeds.testNoneMatch': 'Intet i dette feed passer til dit titelfilter. Sammenlign skrivemåden med titlerne ovenfor.',
  'settings.feeds.testEmpty': 'Adressen svarede, men dokumentet indeholder slet ingen poster. Tjek, om det virkelig er et feed og ikke den side, feedet ligger på.',
  'settings.feeds.testFailed': 'Dette feed kunne ikke læses',
  'settings.headerProfiles.title': 'Header-profiler',
  'settings.headerProfiles.hint': 'Nogle sider udleverer kun en fil til en browser, der er logget ind, eller til et opslag, der kommer fra en af deres egne sider. En profil gemmer headerne for præcis én side, krypteret på samme måde som dine loginoplysninger, og KnightLoader sender dem med ved hver download fra den side.',
  'settings.headerProfiles.empty': 'Ingen header-profiler endnu.',
  'settings.headerProfiles.emptyHint': 'En er værd at have, så snart en download kun virker, mens du er logget ind i browseren.',
