  'settings.rules.action.category': 'Kategori',
  'settings.rules.action.categoryHint': 'Lægger links, der passer, i en af skufferne fra listen Kategorier længere nede på denne side, og den bringer sin egen mappe, sin plads i køen, sin kontakt for udpakning og sin regel for navnekonflikter med sig. Lader du feltet stå urørt, har ingen regel en mening om det, og linket bliver liggende usorteret. Nævner denne regel også en downloadmappe, vinder den mappe, og skuffen leverer alt det øvrige. At nævne en skuffe, der er slettet, bliver afvist, når du gemmer, for en regel, der peger på en skuffe, som ikke er der, gør overhovedet ingenting ved hvert eneste link, den passer på, uden en meddelelse.',
  'settings.rules.action.categoryNone': 'Ingen kategorier endnu. Opret først en under Kategorier længere nede på denne side, ellers ville denne regel lægge links i en skuffe, der ikke findes.',
