  'detail.addressHint': 'Den adresse, denne download blev startet med. Det er den, appen har spurgt efter, og det er ikke altid der, hvor byte kom fra: gennem en debrid-tjeneste står der ved Vært nedenfor den side, filen ligger på, og ved Backend, hvem der hentede den.',
  'detail.copy': 'Kopiér',
