  'detail.mirrorOf': 'Reservekopi af',
  'detail.times': 'Tidsstempler',
  'detail.timesHint': 'Hvornår dette link kom ind, hvornår det sidst blev ændret, og hvornår det var færdigt. Der står ikke noget om, hvornår overførslen begyndte: appen noterer det ingen steder, og et gæt ud fra de tre andre ville være et tal, folk handler efter.',
  'detail.nextTry': 'Næste forsøg',
  'detail.stalledSince': 'Står stille siden',
  'detail.retries': 'Hidtidige gentagelser',
  'detail.retriesHint': 'Hvor tit denne download er blevet prøvet igen efter en fejl. Tælleren bliver sat til nul i samme øjeblik, downloaden bliver færdig, så en færdig række viser nul, også når det tog fire anløb. Hvor mange forsøg der er tilbage, står her ikke: loftet afhænger af årsagen og af værten, og denne side kan ikke regne det ud.',
  'detail.stallRestarts': 'Genstarter efter stilstand',
  'detail.stallRestartsHint': 'Hvor tit overvågningen af stilstand har startet denne download igen af sig selv. Den bliver sat til nul, når downloaden bliver færdig, ligesom tælleren ovenfor.',
  'detail.failure': 'Hvad der gik galt',
  'detail.cause': 'Årsag',
  'detail.message': 'Hvad backendet sagde',
  'detail.messageHint': 'Sætningen fra det, der prøvede at hente den her, ord for ord og uoversat. Det er den aktuelle fejl og intet andet: en genstart rydder den, og de tidligere bliver ikke gemt nogen steder.',
  'detail.heldBack': 'Holdes tilbage af',
  'detail.doing': 'Laver lige nu',
  'detail.gaveUp': 'Intet nyt forsøg',
  'detail.gaveUpHint': 'Her er der stoppet med vilje, ikke fordi forsøgene er brugt op: en captcha, en fuld disk eller en regel, der siger aldrig for denne vært. At sætte antallet af gentagelser op ændrer ikke noget her. Selve markeringen bliver ikke skrevet i databasen, så den er væk efter en genstart, selv om grunden til den ikke er.',
  'detail.rules': 'Regler, der har formet den her',
  'detail.rulesHint': 'De regler, der sprang an på dette link, da det blev klargjort, i den rækkefølge de kørte. De står med navn i opgaven: en regel, der er blevet omdøbt siden, bliver ikke fundet mere, og en regel, der aldrig har haft et navn, står med den placering, den havde dengang. Et klik åbner den i regeleditoren.',
  'detail.openRule': 'Åbn i regeleditoren',
  'detail.noRules': 'Ingen regel har rørt dette link.',
  'detail.player': 'Afspil',
  'detail.play': 'Afspil her',
  'detail.playHint': 'Afspiller filen direkte fra denne instans, uden at hente den en gang til. Der bliver ikke hentet noget, før du trykker på afspil, og filen bliver, hvor den er.',
  'detail.playPartial': 'Denne download er ikke færdig. Kun den del, der allerede ligger på disken, kan afspilles, du kan ikke springe længere frem, og nogle filer afspiller slet ingenting, før den sidste byte er der.',
  'detail.playUnsupported': 'Denne browser kan ikke afspille denne fil. Åbn eller gem den fra højreklik-menuen i stedet.',
