  'notifications.title': 'Meddelelser',
  'notifications.titleHint': 'Bestem for hver begivenhed, om den dukker op som en boble i appen, som en meddelelse fra dit styresystem, eller slet ikke. En systemmeddelelse når kun frem til dig, så længe en KnightLoader-fane er åben, og den stille tilstand nedenfor gælder oveni.',
