  'notifications.event.downloadFailed': 'Download mislykkedes',
  'notifications.event.downloadFailedHint': 'En download, der har givet op. Den stille tilstand skjuler den aldrig.',
  'notifications.event.extractionDone': 'Udpakning færdig',
  'notifications.event.extractionDoneHint': 'Et arkiv, der er pakket færdigt ud. Det er ikke blevet meldt nogen steder før, derfor står det i begyndelsen på „Vis ingenting“.',
