  'notifications.event.captchaWaiting': 'Der venter en captcha',
  'notifications.event.captchaWaitingHint': 'Captcha-vinduet åbner i denne fane under alle omstændigheder. Det står i begyndelsen på „Vis ingenting“, fordi det vindue allerede er meddelelsen, så længe du kigger på den. Sæt det til systemmeddelelse, så når en captcha også frem til dig i en baggrundsfane, før værten smider sessionen væk.',
  'notifications.event.captchaFailed': 'Captcha mislykkedes',
  'notifications.event.captchaFailedHint': 'Ingen svarede i tide, eller svaret kom ikke igennem. Downloaden bag den bliver liggende.',
