  'views.deleteTitle': 'Slet visningen „{name}“?',
  'views.deleteBody': 'En visning er kun et navn for en søgning og et par filtre. Når du sletter den, ændrer der sig ikke noget på listen, og der forsvinder ingen links.',
  'views.deleteConfirm': 'Slet visning',
  'views.clearAll': 'Ryd søgningen og alle filtre',
  'views.clearAllHint': 'Søgning og filtre bliver stående, når du forlader siden og kommer tilbage, så du ser den liste igen, du forlod. Hermed henter du hele listen tilbage. Gemte visninger bliver, som de er.',
  'disk.title': 'Målmapper',
  'disk.hint': 'Ledig og brugt plads i hver mappe, en download kan lande i, og hvor meget køen stadig skal skrive i hver af dem. Tallene kommer fra det samme kald, som diskgrænserne tjekkes mod, og er højst et par sekunder gamle. Ledig og brugt giver ikke altid drevets størrelse tilsammen: et filsystem holder en del tilbage til systemet, og en kvote pr. bruger kan give denne instans mindre, end drevet faktisk har. To mapper på samme disk viser hver især den disk, så læg aldrig rækkerne sammen.',
  'disk.free': 'Fri',
  'disk.used': 'Brugt',
  'disk.size': 'Diskens størrelse',
  'disk.queued': 'Skal stadig skrives',
  'disk.queuedHint': 'Hvad de downloads, der stadig skyldes, ville lægge til i denne mappe: den størrelse, værten har oplyst, minus det, der allerede er kommet. En download, hvis størrelse værten ikke vil oplyse, tæller her som nul, så tallet er en underkant og aldrig et løfte, og derfor kan der stå nul byte ved siden af en række downloads. Downloads, du har slået fra, bliver holdt udenfor, samme regel som tællerne under listen følger. En download, der allerede kører, har som regel fået sin plads reserveret på disken i det øjeblik, den startede, så dens byte mangler allerede i den frie plads ved siden af og kommer ikke oveni.',
  'disk.tasks': '{n} download(s)',
  'disk.unknown': 'Dette system melder ikke fri plads',
  'disk.unknownHint': 'Ikke alle kerner kan spørges om, hvor meget plads der er tilbage på et drev, og dette build har intet kald til den, det kører på. Hvor svaret mangler, bliver intet holdt tilbage: downloads starter, som om ingen diskgrænse var sat. Denne linje står her, så du kan skelne det fra en disk, der virkelig er fuld.',
  'disk.missing': 'Ikke oprettet endnu',
  'disk.missingHint': 'Denne mappe bliver oprettet af den, der skriver den første fil ned i den, så den findes ikke endnu. Tallene beskriver {path}, den nærmeste mappe over den, der findes, og den ligger på den disk, downloaden ville lande på.',
  'disk.measured': 'Målt ved {path}',
  'disk.elsewhereHint': 'Selve mappen kunne ikke måles, så her er den nærmeste over den, der kunne. Er et monteringspunkt ikke kommet op, kan det være en helt anden disk end den, downloaden er tænkt til. Se på stien, før du læser noget ud af tallene.',
  'disk.sampled': 'Læst for {n} sekund(er) siden',
  'disk.tight': 'Køen kan ikke være der',
  'disk.tightHint': 'Der skyldes mere til denne mappe, end der er frit på disken. Denne linje stopper ikke noget i sig selv: der bliver holdt tilbage én ad gangen, efterhånden som en download er på tur, efter tallene på indstillingssiden Downloads. En download, hvis størrelse ingen kender, tæller slet ikke med her.',
  'disk.truncated': 'Ikke alle mapper står her',
  'disk.truncatedHint': 'Køen peger på flere mapper uden for de indstillede, end det kan betale sig at måle ved hvert opslag, så dem, der skyldes mindst, er udeladt. Hver mappe, du har indstillet, er altid med.',
  'disk.markLow': 'Herunder starter intet nyt',
  'disk.markStop': 'Herunder stopper alt',
  'disk.limits': 'Indstil diskgrænserne',
  'disk.stripLabel': 'Plads i målmapperne',
  'disk.role.downloads': 'Downloadmappe',
  'disk.role.category': 'Kategorimappe',
  'disk.role.work': 'Arbejdsmappe',
  'disk.role.task': 'Sat på selve downloaden',
  'settings.volume.title': 'Volumenloft',
  'settings.volume.titleHint': 'Hvad denne instans har hentet færdigt, talt op mod et loft, du sætter, pr. periode. Der tælles den størrelse, værten har oplyst for hver færdig download, så alt, der bliver færdigt uden en oplyst størrelse, tæller som nul, og det, en torrent uploader, tæller slet ikke med. Det er en optælling af dine downloads, ikke en måling af din linje: de byte, din router faktisk har flyttet, er der ingen her, der kan se.',
  'settings.volume.cap': 'Loft pr. periode (GB)',
  'settings.volume.capHint': '0 betyder intet loft: tælleren løber videre, og der bliver aldrig holdt noget tilbage. Gigabyte er her regnet decimalt, sådan som en udbyder opgiver sit volumen: 500 GB er 500 000 000 000 byte og ikke 465 GiB. Diskværdierne længere oppe på denne side er binære GiB, en anden enhed til et andet spørgsmål.',
  'settings.volume.resetDay': 'Tælleren starter forfra den',
  'settings.volume.resetDayHint': 'Den dag i måneden, hvor tælleren begynder på nul igen, som regel den dag, dit volumen bliver fornyet. I en måned, der er kortere end den valgte dag, starter den forfra på den måneds sidste dag i stedet og glider aldrig over i den næste. Der regnes efter serverens ur, ikke efter din browsers, for det er serveren, der holder køen tilbage.',
  'settings.volume.action': 'Når loftet er nået',
  'settings.volume.actionHint': 'En overførsel, der allerede kører, afbrydes aldrig, uanset hvilket svar du vælger: at stoppe midt i en fil smider byte væk, du allerede har brugt. „Giv kun besked“ ændrer ingenting, så er tælleren hele funktionen. „Start ikke flere downloads“ lader det, der kører, blive færdigt og holder køen tilbage, indtil tælleren starter forfra, og hver ventende række siger det. „Sæt farten ned for alt“ holder køen i gang med hastigheden nedenfor.',
  'settings.volume.actionReport': 'Giv kun besked',
  'settings.volume.actionPause': 'Start ikke flere downloads',
  'settings.volume.actionThrottle': 'Sæt farten ned for alt',
  'settings.volume.throttle': 'Hastighed efter loftet',
  'settings.volume.throttleHint': 'Den hastighed, der gælder resten af perioden. Det er en øvre grænse ved siden af dine andre grænser og aldrig i stedet for dem: et natligt vindue eller den stille tilstand, der beder om mindre, vinder stadig. 0 ville her betyde slet ingen grænse og dermed det samme som intet loft, så det mindste tal, der giver mening, er 1.',
  'settings.volume.noCap': 'Intet loft',
  'settings.volume.used': 'Hentet i denne periode',
  'settings.volume.usedOf': '{used} af {cap}',
  'settings.volume.resetsOn': 'Starter forfra den {date}',
  'settings.volume.reached': 'Loftet er nået.',
  'volume.title': 'Hentet volumen',
  'volume.titleHint': 'Færdige downloads lagt sammen pr. dag og pr. måned, ud af downloadhistorikken. Historikken har sin egen grænse og kan tømmes i hånden, så måneder, der er faldet ud bagi, mangler her helt enkelt. En download, du har startet forfra, tæller én gang, på den dag den sidst blev færdig. Der regnes efter serverens kalender, i {zone}.',
  'volume.range.days': '30 dage',
  'volume.range.months': '12 måneder',
  'volume.split.total': 'Alt',
  'volume.split.host': 'Efter vært',
  'volume.split.backend': 'Efter backend',
  'volume.other': 'Alt det øvrige',
  'volume.empty': 'Der er endnu ikke blevet noget færdigt i denne periode.',
  'volume.unsizedHint': '{n} af disse downloads blev færdige, uden at værten nogensinde oplyste en størrelse. De lægger intet til summen, så det virkelige tal er højere end det, der er tegnet her.',
  'volume.trimmedHint': 'Historikken er ved sin egen grænse, så alt, der er ældre end dens ældste post, mangler også i denne kurve. Sæt historikkens grænse op på denne side, hvis du vil se længere tilbage.',
  'volume.meter': 'Volumen',
  'volume.meterHint': 'Hvad der er hentet færdigt, siden tælleren sidst startede forfra, målt mod loftet på indstillingssiden Downloads. Tallet ændrer sig, når en download bliver færdig, ikke mens den kører. Det lægges sammen ud fra downloadhistorikken, så tømmer du historikken, sættes denne tæller også til nul.',
