  'task.retry.pending': 'Forsøg {n} af {max}, næste om {countdown}',
  'task.retry.pendingNoMax': 'Forsøg {n}, næste om {countdown}',
  'task.retry.due': 'Forsøg {n} af {max}, starter nu',
