  'settings.selftest.jd': 'JDownloader-backend',
  'settings.selftest.jd.ok': 'Kan nås, revision {version}.',
  'settings.selftest.jd.provisioningOff': 'Den automatiske opsætning er slået fra, og der er ikke sat nogen adresse, så der er ingen backend at nå.',
