  'settings.selftest.jd.missingAdvice': 'Dette build starter normalt sin egen hovedløse JDownloader under opstarten og udfylder selv KL_JD. At den er tom, betyder, at den start slog fejl. Se efter "JD provisioning failed" i loggen længere nede, eller sæt KL_JD til din egen JDownloader.',
  'settings.selftest.jd.unreachable': '{address} svarede ikke.',
  'settings.selftest.jd.unreachableAdvice': 'Adressen er gemt, og intet lytter på den. Tjek, at backenden kører, og at dens port 3128 kan nås inde fra denne container, ikke kun fra værten.',
  'settings.selftest.jd.noVersion': 'Svarer, men vil ikke sige, hvilken revision det er.',
  'settings.selftest.ytdlp': 'yt-dlp',
  'settings.selftest.ytdlp.ok': '{version}, {days} dage gammel.',
  'settings.selftest.ytdlp.aging': '{version} er {days} dage gammel.',
  'settings.selftest.ytdlp.old': '{version} er {days} dage gammel. De store videosider ødelægger det som regel i løbet af få uger.',
  'settings.selftest.ytdlp.oldAdvice': 'I containeren kommer yt-dlp fra den Alpine-pakke, der var aktuel, da imaget blev bygget, og det opdaterer sig aldrig selv. Hent et nyere image, eller hæng dit eget yt-dlp ind i containeren, og lad KL_YTDLP pege på det.',
