  'settings.selftest.ytdlp.undated': '{version} ligner ikke en dato, så alderen kan ikke bedømmes.',
  'settings.selftest.folders': 'Download- og arbejdsmappe',
  'settings.selftest.folders.allOk': 'Hver mappe, der blev tjekket, er der og kan skrives i.',
  'settings.selftest.folders.someBad': 'Ved mindst én mappe er der noget at se på.',
  'settings.selftest.folders.none': 'Der kunne slet ikke måles nogen mappe.',
  'settings.selftest.folders.ok': 'Der kan skrives i {dir}, {free} frit.',
  'settings.selftest.folders.notWritable': 'Der kan ikke skrives i {dir}.',
  'settings.selftest.folders.notWritableAdvice': 'Denne proces kører som uid {uid}. Se efter, hvem mappen tilhører på værten, og om den uid må skrive i den.',
