  'settings.selftest.folders.low': 'Kun {free} tilbage på {dir}, under de {mark}, hvor køen stopper.',
  'settings.selftest.folders.noMark': '{free} frit på {dir}. Du har ikke sat nogen fast grænse, så køen holder kun en download tilbage, når den alligevel ikke kan være der.',
  'settings.selftest.folders.unknown': 'Denne platform kan ikke spørges om, hvor meget plads der er på {dir}.',
  'settings.selftest.accounts': 'Debrid-logins',
  'settings.selftest.accounts.none': 'Der er ikke sat nogen debrid-konto op, så der var ikke noget at tjekke.',
  'settings.selftest.accounts.allOk': 'Alle {n} logins blev godkendt.',
  'settings.selftest.accounts.someFailed': '{bad} af {n} logins blev afvist.',
