  'auth.twoFactor.codesTitle': 'Skriv dem ned nu',
  'auth.twoFactor.codesHint': 'Det er eneste gang, de bliver vist. Hver gælder én gang i stedet for en kode fra appen, og de er alt, hvad der lukker dig ind igen, hvis telefonen bliver væk.',
  'auth.twoFactor.codesAck': 'Jeg har skrevet dem ned',
  'auth.twoFactor.recoveryLeft': '{n} gendannelseskoder tilbage.',
  'auth.twoFactor.disable': 'Slå fra',
